function recordToForm(r) {
    return {
        category: r.category,
        propertyName: r.propertyName,
        address: r.address,
        description: r.description,
        starRating: r.starRating != null ? String(r.starRating) : "",
        totalRooms: r.totalRooms != null ? String(r.totalRooms) : "",
        parkingAvailable: r.parkingAvailable,
        parkingSpaces: r.parkingSpaces != null ? String(r.parkingSpaces) : "",
        rooms: (r.rooms ?? []).map((rm)=>({
                roomType: rm.roomType ?? "",
                price: rm.price != null ? String(rm.price) : "",
                hours: rm.hours != null ? String(rm.hours) : "",
                beds: rm.beds != null ? String(rm.beds) : "",
                maxGuests: rm.maxGuests != null ? String(rm.maxGuests) : "",
                amenities: [
                    ...rm.amenities ?? []
                ]
            })),
        photos: [
            ...r.photos ?? []
        ],
        bedrooms: r.bedrooms != null ? String(r.bedrooms) : "",
        bathrooms: r.bathrooms != null ? String(r.bathrooms) : "",
        beds: r.beds != null ? String(r.beds) : "",
        maxGuests: r.maxGuests != null ? String(r.maxGuests) : "",
        hasHall: r.hasHall ?? false,
        hasKitchen: r.hasKitchen ?? false,
        hasPrivatePool: r.hasPrivatePool ?? false,
        propertySize: r.propertySize ?? "",
        villaAmenities: [
            ...r.villaAmenities ?? []
        ],
        villaPrice: r.villaPrice != null ? String(r.villaPrice) : "",
        villaHours: r.villaHours != null ? String(r.villaHours) : ""
    };
}
